export default "import {\n  SceneFlexLayout,\n  EmbeddedScene,\n  SceneFlexItem,\n  SceneAppPage,\n  SceneAppPageState,\n  PanelBuilders,\n  SceneQueryRunner,\n  SceneCanvasText,\n  SceneVariableSet,\n  VariableValueSelectors,\n  GroupByVariable,\n} from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults } from './utils';\n\nexport function getGroupByStatic(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        $variables: new SceneVariableSet({\n          variables: [\n            new GroupByVariable({\n              name: 'groupBy',\n              label: 'Group By MultiSelect (static list)',\n              datasource: { uid: 'gdev-prometheus' },\n              defaultOptions: [\n                {\n                  text: 'instance',\n                  value: 'instance',\n                },\n                {\n                  text: 'job',\n                  value: 'job',\n                },\n                {\n                  text: 'alert_name',\n                  value: 'alert_name',\n                },\n              ],\n            }),\n            new GroupByVariable({\n              name: 'groupByOneSelection',\n              label: 'Group By OneSelection (static list)',\n              datasource: { uid: 'gdev-prometheus' },\n              isMulti: false,\n              defaultOptions: [\n                {\n                  text: 'schema',\n                  value: 'schema',\n                },\n                {\n                  text: 'instance',\n                  value: 'instance',\n                },\n                {\n                  text: 'job',\n                  value: 'job',\n                },\n              ],\n            }),\n          ],\n        }),\n        controls: [new VariableValueSelectors({})],\n        ...getEmbeddedSceneDefaults().controls,\n        body: new SceneFlexLayout({\n          direction: 'column',\n          children: [\n            new SceneFlexItem({\n              ySizing: 'content',\n              body: new SceneCanvasText({\n                text: `Interpolated value MultiSelect(static): {$groupBy}`,\n                fontSize: 14,\n              }),\n            }),\n            new SceneFlexItem({\n              ySizing: 'content',\n              body: new SceneCanvasText({\n                text: `Interpolated value OneSelection (static): {$groupByOneSelection}`,\n                fontSize: 14,\n              }),\n            }),\n            new SceneFlexItem({\n              body: PanelBuilders.table()\n                .setTitle('ALERTS')\n                .setData(\n                  new SceneQueryRunner({\n                    datasource: { uid: 'gdev-prometheus' },\n                    queries: [\n                      {\n                        refId: 'A',\n                        expr: 'count(ALERTS)',\n                        format: 'table',\n                        instant: true,\n                      },\n                    ],\n                  })\n                )\n                .build(),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n";